declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';$user=require_permission('documents.write');\App\Core\Tenant::enforceActive((int)$user['tenant_id']);$t=(int)$user['tenant_id'];$sql="SELECT * FROM patients WHERE tenant_id=:t AND status='active' AND primary_professional_id=:u ORDER BY name";$st=db()->prepare($sql);$st->execute(['t'=>$t,'u'=>$user['id']]);$patients=$st->fetchAll();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pid=(int)($_POST['patient_id']??0);$patient=null;foreach($patients as $x)if((int)$x['id']===$pid)$patient=$x;if(!$patient||!\App\Core\Rbac::canViewPatientClinical($user,$patient))$error='Paciente não autorizado.';else{$type=$_POST['document_type']??'relatorio';if(!in_array($type,['declaracao','atestado','relatorio','laudo','parecer'],true))$type='relatorio';$title=trim($_POST['title']??'');$content=['identificacao'=>trim($_POST['identificacao']??''),'descricao_demanda'=>trim($_POST['descricao_demanda']??''),'procedimento'=>trim($_POST['procedimento']??''),'analise'=>trim($_POST['analise']??''),'conclusao'=>trim($_POST['conclusao']??'')];if(!$title||!array_filter($content))$error='Informe título e conteúdo.';else{$status=$user['role_slug']==='supervised'?'pending_approval':'draft';$sup=$user['role_slug']==='supervised'?(int)($user['supervisor_id']??0):null;if($status==='pending_approval'&&$sup<1)$error='Supervisor não configurado.';else{$token=bin2hex(random_bytes(32));$st=db()->prepare("INSERT INTO clinical_documents(tenant_id,patient_id,professional_id,supervisor_id,document_type,title,content_enc,status,compliance_status,validation_token,created_at,updated_at)VALUES(:t,:p,:u,:s,:type,:title,:c,:status,'not_checked',:token,NOW(),NOW())");$st->execute(['t'=>$t,'p'=>$pid,'u'=>$user['id'],'s'=>$sup?:null,'type'=>$type,'title'=>$title,'c'=>\App\Core\Crypto::encrypt($content),'status'=>$status,'token'=>$token]);$id=(int)db()->lastInsertId();audit('clinical.document_create','clinical_document',$id,['type'=>$type,'patient_id'=>$pid]);redirect('documents/view.php?id='.$id);}}}}
layout('Novo documento',function()use($patients,$error){?><div class="page-head"><div><span class="eyebrow">Documentos</span><h1>Novo documento psicológico</h1><p>Estrutura assistida. O profissional permanece responsável pela redação, revisão e assinatura.</p></div></div><form method="post" class="card form-grid"><?=csrf_field()?><?php if($error):?><div class="error-box"><?=e($error)?></div><?php endif?><div class="form-row"><div class="field"><label>Paciente</label><select name="patient_id" required><?php foreach($patients as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?></option><?php endforeach?></select></div><div class="field"><label>Tipo</label><select name="document_type"><?php foreach(['declaracao'=>'Declaração','atestado'=>'Atestado psicológico','relatorio'=>'Relatório psicológico','laudo'=>'Laudo psicológico','parecer'=>'Parecer'] as $k=>$v):?><option value="<?=$k?>"><?=$v?></option><?php endforeach?></select></div></div><div class="field"><label>Título</label><input name="title" required placeholder="Ex.: Relatório psicológico para finalidade ..."></div><?php foreach(['identificacao'=>'Identificação e finalidade','descricao_demanda'=>'Descrição da demanda','procedimento'=>'Procedimentos','analise'=>'Análise','conclusao'=>'Conclusão'] as $k=>$label):?><div class="field"><label><?=$label?></label><textarea name="<?=$k?>"></textarea></div><?php endforeach?><div class="help">Use o Copiloto em modo “Auditoria” para revisar estrutura e depois marque a conferência no documento.</div><button class="button">Salvar rascunho</button></form><?php },['active'=>'documents']);
